#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ofstream out("nums.txt");
    out << 10 << " " << 20 << " " << 30 << " " << 40 << endl;
    out.close();

    ifstream in("nums.txt");
    if (!in) {
        cout << "File not found!" << endl;
        return 1;
    }
    int x;
    int sum = 0;
    while (in >> x) {
        sum += x;
        cout << "read " << x << endl;
    }
    in.close();
    cout << "Sum = " << sum << endl;
    return 0;
}

#include <iostream>
#include <fstream>
#include <string>
using namespace std;

int main() {
    ofstream out("story.txt");
    out << "Ali scored well" << endl;
    out << "Sana did better" << endl;
    out << "Usman tried" << endl;
    out.close();

    ifstream in("story.txt");
    if (!in) {
        cout << "File not found!" << endl;
        return 1;
    }
    string line;
    int lines = 0;
    while (getline(in, line)) {
        lines++;
        cout << "Line " << lines << ": " << line << endl;
    }
    in.close();

    ifstream again("story.txt");
    string word;
    int words = 0;
    while (again >> word) {
        words++;
    }
    again.close();
    cout << "Lines: " << lines << ", words: " << words << endl;
    return 0;
}

#include <iostream>
#include <fstream>
#include <string>
using namespace std;

int main() {
    ofstream out("students.txt");
    out << "101 Ali 78" << endl;
    out << "102 Sana 91" << endl;
    out << "103 Usman 66" << endl;
    out << "104 Hira 88" << endl;
    out.close();

    ifstream in("students.txt");
    if (!in) {
        cout << "File not found!" << endl;
        return 1;
    }
    int roll;
    string name;
    double marks;
    double total = 0;
    int count = 0;
    double best = 0;
    string bestName = "";
    while (in >> roll >> name >> marks) {
        cout << roll << " - " << name << " - " << marks << endl;
        total += marks;
        count++;
        if (marks > best) {
            best = marks;
            bestName = name;
        }
    }
    in.close();
    if (count > 0) {
        cout << "Students: " << count << endl;
        cout << "Average: " << total / count << endl;
        cout << "Top: " << bestName << " with " << best << endl;
    }
    return 0;
}

