#include <iostream>
#include <fstream>
using namespace std;
int main() {
    ofstream out("scores.txt");
    out << 70 << " " << 85 << " " << 90 << " " << 55 << endl;
    out.close();
    ifstream in("scores.txt");
    if (!in) { cout << "File not found!" << endl; return 1; }
    int x, largest = 0;
    while (in >> x) {
        if (x > largest) largest = x;
    }
    in.close();
    cout << "Largest: " << largest << endl;
    return 0;
}
